// Normaliza o payload recebido de qualquer fonte externa
// (Typeform, landing page, formulário manual, etc.)
const body = $input.first().json.body ?? $input.first().json;

const normalized = {
  nome_contato: body.nome_contato ?? body.name ?? body.nome ?? "",
  email:        body.email ?? "",
  telefone:     body.telefone ?? body.phone ?? body.tel ?? null,
  empresa:      body.empresa ?? body.company ?? null,
  cnpj:         body.cnpj ?? null,
  setores:      Array.isArray(body.setores) ? body.setores
                : body.setor ? [body.setor]
                : body.sector ? [body.sector]
                : [],
  ufs:          Array.isArray(body.ufs) ? body.ufs
                : body.uf ? [body.uf]
                : [],
  ticket_min:   Number(body.ticket_min ?? body.ticketMin ?? body.min ?? 0),
  ticket_max:   Number(body.ticket_max ?? body.ticketMax ?? body.max ?? 0),
  tipos_operacao: Array.isArray(body.tipos_operacao) ? body.tipos_operacao : [],
  criterios:    body.criterios ?? body.criteria ?? body.notas ?? null,
  origem:       body.origem ?? "n8n_w6",
};

// Validação básica
const errors = [];
if (!normalized.nome_contato) errors.push("nome_contato obrigatório");
if (!normalized.email)        errors.push("email obrigatório");
if (!normalized.setores.length) errors.push("setores[] obrigatório");
if (!normalized.ticket_min)   errors.push("ticket_min obrigatório");
if (!normalized.ticket_max)   errors.push("ticket_max obrigatório");

if (errors.length) {
  throw new Error("Payload inválido: " + errors.join(" | "));
}

return [{ json: { normalized, _valid: true } }];
